using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Web.Script.Serialization;
public static class MillenniumSharing {
 static string Marker{get{return Path.Combine(Engine.Home,@"Data\millennium-import.json");}}
 public static bool CanDisable{get{return Engine.Current!=null&&File.Exists(Marker)&&File.Exists(Path.Combine(Engine.NativeRoot,@"Client\wsock32.dll"));}}
 public static void Disable(){if(Engine.SecondSteam().Length>0)throw new IOException("Quit Second Steam first.");var record=new JavaScriptSerializer().Deserialize<Dictionary<string,string>>(File.ReadAllText(Marker));string file=Path.Combine(Engine.NativeRoot,@"Client\wsock32.dll");NoLinks(file);if(record["Root"]!=Engine.NativeRoot||DualSteam.UpdatePackage.Hash(file)!=record["Hash"])throw new IOException("The runtime changed after import. It was not disabled. Use Millennium’s own uninstaller for that installation.");string backup=Path.Combine(Engine.Home,@"Backups\Millennium",DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fff")+"-disabled-wsock32.dll");Directory.CreateDirectory(Path.GetDirectoryName(backup));File.Move(file,backup);File.Delete(Marker);}
 static string Main{get{return Path.GetDirectoryName(Engine.Current==null?Engine.DetectSteam():Engine.Current.MainSteam)??"";}}
 public static bool Detected{get{return File.Exists(Path.Combine(Main,"wsock32.dll"))&&File.Exists(Path.Combine(Main,@"millennium\lib\millennium.dll"));}}
 public static bool ThemesDetected{get{return Detected&&Directory.Exists(Path.Combine(Main,@"millennium\themes"))&&Directory.GetDirectories(Path.Combine(Main,@"millennium\themes")).Length>0;}}
 public static bool ConfigDetected{get{return Detected&&File.Exists(Path.Combine(Main,@"millennium\config\config.json"));}}
 public static bool PluginsDetected{get{return Detected&&Directory.Exists(Path.Combine(Main,@"millennium\plugins"))&&Directory.GetDirectories(Path.Combine(Main,@"millennium\plugins")).Length>0;}}
 public static void NoLinks(string path){for(string p=Path.GetFullPath(path);!String.IsNullOrEmpty(p);p=Path.GetDirectoryName(p))if((Directory.Exists(p)||File.Exists(p))&&(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new IOException("Linked import paths are not supported: "+Path.GetFileName(path));}
 static IEnumerable<string> Files(string folder){NoLinks(folder);foreach(string file in Directory.GetFiles(folder)){NoLinks(file);yield return file;}foreach(string child in Directory.GetDirectories(folder)){if(new[]{".git","node_modules","__pycache__","crashes","logs"}.Contains(Path.GetFileName(child),StringComparer.OrdinalIgnoreCase))continue;foreach(string file in Files(child))yield return file;}}
 static void AddTree(Dictionary<string,byte[]> files,string folder){if(!Directory.Exists(folder))return;foreach(string file in Files(folder)){if(files.Count>10000)throw new IOException("Too many add-on files.");if(new FileInfo(file).Length>64L*1024*1024)throw new IOException("An add-on file exceeds 64 MB.");files.Add(file.Substring(Main.Length+1),File.ReadAllBytes(file));}}
 public static Dictionary<string,byte[]> Plan(){if(!Detected)throw new IOException("Millennium was not detected in Main Steam.");var p=Preferences.Current;var files=new Dictionary<string,byte[]>(StringComparer.OrdinalIgnoreCase);if(p.ImportMillennium){NoLinks(Path.Combine(Main,"wsock32.dll"));files.Add("wsock32.dll",File.ReadAllBytes(Path.Combine(Main,"wsock32.dll")));AddTree(files,Path.Combine(Main,@"millennium\lib"));AddTree(files,Path.Combine(Main,@"millennium\bin"));}if(p.ImportThemes)AddTree(files,Path.Combine(Main,@"millennium\themes"));if(p.ImportPlugins)AddTree(files,Path.Combine(Main,@"millennium\plugins"));
  if(p.ImportThemeSettings&&ConfigDetected){string target=Path.Combine(Engine.NativeRoot,@"Client\millennium\config\config.json");var json=new JavaScriptSerializer{MaxJsonLength=4000000};NoLinks(Path.Combine(Main,@"millennium\config\config.json"));var source=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(Main,@"millennium\config\config.json")));var merged=File.Exists(target)?json.Deserialize<Dictionary<string,object>>(File.ReadAllText(target)):new Dictionary<string,object>();foreach(string key in new[]{"general","notifications","themes"})if(source.ContainsKey(key))merged[key]=source[key];if(p.ImportPlugins&&source.ContainsKey("plugins"))merged["plugins"]=source["plugins"];files[@"millennium\config\config.json"]=new UTF8Encoding(false).GetBytes(json.Serialize(merged));string css=Path.Combine(Main,@"millennium\config\quick.css");if(File.Exists(css)){NoLinks(css);files[@"millennium\config\quick.css"]=File.ReadAllBytes(css);}}
  if(files.Count==0)throw new IOException("Choose at least one detected Millennium component.");if(files.Sum(f=>(long)f.Value.Length)>512L*1024*1024)throw new IOException("The selected add-ons exceed 512 MB.");return files;
 }
 public static string Import(){if(Engine.Current==null)throw new IOException("Set up Second Steam first.");if(Engine.SecondSteam().Length>0)throw new IOException("Quit Second Steam before importing add-ons. Main Steam can stay open.");var files=Plan();string destination=Path.Combine(Engine.NativeRoot,"Client");NoLinks(destination);string backup=Path.Combine(Engine.Home,@"Backups\Millennium",DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fff"));Directory.CreateDirectory(backup);var old=new Dictionary<string,string>();var applied=new List<string>();
  try{foreach(var item in files){string target=Path.Combine(destination,item.Key);NoLinks(target);if(File.Exists(target)){string saved=Path.Combine(backup,item.Key);Directory.CreateDirectory(Path.GetDirectoryName(saved));File.Copy(target,saved);old[item.Key]=saved;}else old[item.Key]=null;}foreach(var item in files){string target=Path.Combine(destination,item.Key);Directory.CreateDirectory(Path.GetDirectoryName(target));applied.Add(item.Key);File.WriteAllBytes(target+".import-new",item.Value);if(File.Exists(target))File.Replace(target+".import-new",target,null);else File.Move(target+".import-new",target);if(!File.ReadAllBytes(target).SequenceEqual(item.Value))throw new IOException("An imported file did not verify.");}}
  catch{foreach(string relative in applied){string target=Path.Combine(destination,relative);if(old[relative]!=null)File.Copy(old[relative],target,true);else if(File.Exists(target))File.Delete(target);}throw;}
  File.WriteAllText(Path.Combine(backup,"manifest.json"),new JavaScriptSerializer().Serialize(old));if(Preferences.Current.ImportMillennium)File.WriteAllText(Marker,new JavaScriptSerializer().Serialize(new Dictionary<string,string>{{"Root",Engine.NativeRoot},{"Hash",DualSteam.UpdatePackage.Hash(Path.Combine(destination,"wsock32.dll"))}}));Engine.Log("Imported "+files.Count+" Millennium files; backup "+backup);return "Imported "+files.Count+" files. "+(File.Exists(Path.Combine(destination,"wsock32.dll"))?"Restart Second Steam to load the selected add-ons.":"Import the Millennium runtime too if you want these themes to load.")+" Proxy credentials and Steam logins were not copied.";
 }
}
